<template><div class="academic-page"><div class="page-header-row"><div><span class="eyebrow">একাডেমিক বিভাগ</span><h1>একাডেমিক কেন্দ্র</h1><p>শ্রেণি, সেকশন ও বিষয় এক জায়গা থেকে দেখুন</p></div><div class="academic-search"><icon name="search" /><input v-model="search" placeholder="শ্রেণি, সেকশন বা বিষয় খুঁজুন..." /></div></div><div class="summary-grid"><div class="summary-card green"><span><icon name="academic" /></span><b>{{ classes.length }}</b><small>শ্রেণি</small></div><div class="summary-card blue"><span><icon name="layers" /></span><b>{{ sections.length }}</b><small>সেকশন</small></div><div class="summary-card purple"><span><icon name="book" /></span><b>{{ subjects.length }}</b><small>বিষয়</small></div><div class="summary-card gold"><span><icon name="check" /></span><b>{{ filteredSubjects.length }}</b><small>সার্চে মিল</small></div></div><div class="tabs"><button v-for="tab in tabs" :key="tab.value" :class="{active:activeTab===tab.value}" @click="activeTab=tab.value">{{ tab.label }}</button></div><div v-if="loading" class="loading-state"><div class="spinner" /><p>একাডেমিক তথ্য লোড হচ্ছে...</p></div><div v-else class="content-panel"><section v-if="activeTab==='classes'" class="class-grid"><article v-for="c in filteredClasses" :key="c.id" class="class-card"><div class="class-icon"><icon name="academic" /></div><div><h3>{{ c.name_bn }}</h3><p>{{ c.name_en || 'ইংরেজি নাম নেই' }}</p><span>{{ c.class_type || 'সাধারণ' }} · গ্রেড {{ c.grade_level || '—' }}</span></div><strong>{{ sectionsFor(c.id).length }}<small> সেকশন</small></strong></article><div v-if="!filteredClasses.length" class="empty-inline">কোনো শ্রেণি পাওয়া যায়নি</div></section><section v-else-if="activeTab==='sections'" class="section-grid"><article v-for="s in filteredSections" :key="s.id" class="section-card"><span class="section-badge">{{ className(s.class_id).charAt(0) || 'স' }}</span><div><h3>{{ s.name_bn }}</h3><p>{{ className(s.class_id) }}</p></div><icon name="chevron-right" /></article><div v-if="!filteredSections.length" class="empty-inline">কোনো সেকশন পাওয়া যায়নি</div></section><section v-else class="subject-grid"><article v-for="s in filteredSubjects" :key="s.id" class="subject-card"><span class="subject-icon"><icon name="book" /></span><div><h3>{{ s.name_bn }}</h3><p>{{ s.name_en || 'ইংরেজি নাম নেই' }}</p></div><span class="subject-type">{{ s.subject_type || 'সাধারণ' }}</span></article><div v-if="!filteredSubjects.length" class="empty-inline">কোনো বিষয় পাওয়া যায়নি</div></section></div></div></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{useApiClient}from'~/utils/api';const api=useApiClient();const loading=ref(true);const search=ref('');const activeTab=ref('classes');const classes=ref<any[]>([]);const sections=ref<any[]>([]);const subjects=ref<any[]>([]);const tabs=[{value:'classes',label:'শ্রেণিসমূহ'},{value:'sections',label:'সেকশনসমূহ'},{value:'subjects',label:'বিষয়সমূহ'}];const match=(v:any)=>String(v||'').toLowerCase().includes(search.value.toLowerCase());const filteredClasses=computed(()=>classes.value.filter(x=>!search.value||match(x.name_bn)||match(x.name_en)));const filteredSections=computed(()=>sections.value.filter(x=>!search.value||match(x.name_bn)||match(className(x.class_id))));const filteredSubjects=computed(()=>subjects.value.filter(x=>!search.value||match(x.name_bn)||match(x.name_en)||match(x.subject_type)));function className(id:number){return classes.value.find(c=>c.id===id)?.name_bn||'শ্রেণি নির্ধারিত নয়'}function sectionsFor(id:number){return sections.value.filter(s=>s.class_id===id)}onMounted(async()=>{try{const[c,s,sub]=await Promise.all([api.get('/academic/classes'),api.get('/academic/sections'),api.get('/academic/subjects')]);classes.value=c.data?.data||[];sections.value=s.data?.data||[];subjects.value=sub.data?.data||[]}catch(e){console.error(e)}finally{loading.value=false}})</script>
<style scoped>.academic-page{max-width:1400px;margin:0 auto;padding-bottom:2rem}.page-header-row{display:flex;justify-content:space-between;align-items:flex-end;gap:1rem;margin-bottom:1.4rem}.eyebrow{color:var(--color-primary);font:600 .78rem var(--font-bn)}.page-header-row h1{margin:.25rem 0;color:var(--color-primary);font:700 1.65rem var(--font-bn)}.page-header-row p{color:var(--color-text-light);font:.88rem var(--font-bn)}.academic-search{display:flex;align-items:center;gap:.5rem;width:300px;padding:.65rem .8rem;background:#fff;border:1px solid var(--color-border);border-radius:12px}.academic-search input{width:100%;border:0;outline:0;background:transparent;font:.78rem var(--font-bn)}.summary-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:.8rem;margin-bottom:1.2rem}.summary-card{display:grid;grid-template-columns:auto 1fr;align-items:center;column-gap:.7rem;padding:1rem;border-radius:15px;color:#fff}.summary-card span{display:grid;place-items:center;width:38px;height:38px;border-radius:11px;background:rgba(255,255,255,.17)}.summary-card b{font:800 1.35rem var(--font-sans)}.summary-card small{grid-column:2;color:rgba(255,255,255,.78);font:.72rem var(--font-bn)}.summary-card.green{background:linear-gradient(145deg,#176b45,#0e452d)}.summary-card.blue{background:linear-gradient(145deg,#17658f,#103b60)}.summary-card.purple{background:linear-gradient(145deg,#6e4da5,#41316f)}.summary-card.gold{background:linear-gradient(145deg,#bd8e20,#795a12)}.tabs{display:flex;gap:.3rem;margin-bottom:1rem;padding:.25rem;background:#fff;border:1px solid var(--color-border-light);border-radius:12px;width:max-content}.tabs button{padding:.55rem 1rem;border:0;border-radius:9px;background:transparent;color:var(--color-text-light);font:.78rem var(--font-bn);cursor:pointer}.tabs button.active{color:#fff;background:var(--color-primary)}.content-panel{min-height:300px}.class-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}.class-card,.section-card,.subject-card{background:#fff;border:1px solid var(--color-border-light);border-radius:16px;box-shadow:var(--shadow-sm);transition:.2s}.class-card:hover,.section-card:hover,.subject-card:hover{transform:translateY(-3px);box-shadow:var(--shadow-md)}.class-card{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:.7rem;padding:1rem}.class-icon,.subject-icon{display:grid;place-items:center;width:42px;height:42px;border-radius:13px;color:var(--color-primary);background:var(--color-primary-50)}.class-card h3,.subject-card h3,.section-card h3{font:700 .9rem var(--font-bn)}.class-card p,.class-card span,.subject-card p,.section-card p{display:block;margin-top:.15rem;color:var(--color-text-light);font:.7rem var(--font-bn)}.class-card strong{color:var(--color-primary);font:800 1.1rem var(--font-sans)}.class-card strong small{font:400 .65rem var(--font-bn)}.section-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:.8rem}.section-card{display:flex;align-items:center;gap:.7rem;padding:.9rem}.section-card>svg{margin-left:auto;color:var(--color-text-muted)}.section-badge{display:grid;place-items:center;width:34px;height:34px;border-radius:10px;color:#7857a9;background:#f0eafb;font:700 .85rem var(--font-bn)}.subject-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:.8rem}.subject-card{display:flex;align-items:center;gap:.65rem;padding:.8rem}.subject-icon{width:36px;height:36px;flex:0 0 36px}.subject-type{margin-left:auto;padding:.2rem .45rem;border-radius:99px;color:#7857a9;background:#f0eafb;font:.62rem var(--font-bn)}.empty-inline{grid-column:1/-1;padding:3rem;text-align:center;color:var(--color-text-muted);font:.8rem var(--font-bn)}@media(max-width:1000px){.class-grid,.section-grid{grid-template-columns:repeat(2,1fr)}.subject-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){.page-header-row{align-items:flex-start;flex-direction:column}.academic-search{width:100%}.summary-grid{grid-template-columns:repeat(2,1fr)}.class-grid,.section-grid,.subject-grid{grid-template-columns:1fr}.tabs{width:100%;overflow:auto}.tabs button{flex:1;white-space:nowrap}}
</style>
